#include <stdio.h>
#include <stdlib.h>
#include "dk1/rom_image.h"
#include "dk1/scene_memory.h"
#include "dk1/scene_signature.h"
#include "dk1/software_frontend.h"
int main(int argc,char**argv){Dk1OwnedRom owned={0};Dk1RomImage rom={0};Dk1RomIdentity identity;Dk1SceneMemory*scene=NULL;Dk1Rgba8*pixels=NULL;Dk1RgbaSurface surface;uint64_t hash=0;uint16_t level;size_t failed=0,terrain=0,local=0;if(argc!=2)return 2;if(!dk1_rom_load_file(argv[1],&owned,&rom)||!dk1_rom_identity(&rom,&identity)||!dk1_rom_identity_is_supported_rev2(&identity))return 1;scene=malloc(sizeof(*scene));pixels=calloc(96u*64u,sizeof(*pixels));if(!scene||!pixels){free(scene);free(pixels);dk1_rom_free(&owned);return 1;}surface=(Dk1RgbaSurface){pixels,96u,64u,96u};for(level=0;level<DK1_SCENE_LEVEL_COUNT;level++){Dk1SoftwareFrontend f;if(!dk1_scene_memory_load(&rom,level,false,false,scene)||!dk1_software_frontend_init_with_rom(&rom,scene,96u,64u,&f)||!dk1_software_frontend_step(scene,DK1_HOST_BUTTON_B,&f)||!dk1_software_frontend_render(&rom,scene,&f,surface)){failed++;continue;}if(f.player_terrain_ready)terrain++;if(f.player_live.used_local_semantics)local++;hash=dk1_fnv1a64(&level,sizeof(level),hash);hash=dk1_fnv1a64(&f.runtime,sizeof(f.runtime),hash);hash=dk1_fnv1a64(&f.player_preview,sizeof(f.player_preview),hash);hash=dk1_fnv1a64(&f.player_live,sizeof(f.player_live),hash);hash=dk1_fnv1a64(pixels,96u*64u*sizeof(*pixels),hash);}printf("frontends=%u failed=%zu terrain=%zu local_dispatch=%zu signature=%016llX\n",DK1_SCENE_LEVEL_COUNT,failed,terrain,local,(unsigned long long)hash);free(scene);free(pixels);dk1_rom_free(&owned);return failed?1:0;}
